package com.transportplatform.tms.features.driverearnings.api;
import com.transportplatform.tms.common.response.ApiResponse; import com.transportplatform.tms.features.driverearnings.api.request.*; import com.transportplatform.tms.features.driverearnings.api.response.*; import com.transportplatform.tms.features.driverearnings.application.DriverEarningsService; import jakarta.validation.Valid; import java.math.BigDecimal; import java.util.List; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController public class DriverEarningsController { private final DriverEarningsService service; public DriverEarningsController(DriverEarningsService service){this.service=service;} @GetMapping("/portal/driver/payments") @PreAuthorize("hasRole('DRIVER')") public ApiResponse<DriverEarningsSummaryResponse> mine(){return ApiResponse.success(service.myEarnings());} @GetMapping("/company/driver-earnings") @PreAuthorize("hasRole('TENANT_ADMIN')") public ApiResponse<List<DriverEarningsEntryResponse>> list(){return ApiResponse.success(service.listAdmin());} @GetMapping("/company/driver-earnings/rate") @PreAuthorize("hasRole('TENANT_ADMIN')") public ApiResponse<BigDecimal> rate(){return ApiResponse.success(service.getRate());} @PutMapping("/company/driver-earnings/rate") @PreAuthorize("hasRole('TENANT_ADMIN')") public ApiResponse<BigDecimal> rate(@Valid @RequestBody DriverEarningsRateRequest r){return ApiResponse.success(service.updateRate(r));} @PostMapping("/company/driver-earnings/adjustments") @PreAuthorize("hasRole('TENANT_ADMIN')") public ApiResponse<DriverEarningsEntryResponse> adjust(@Valid @RequestBody DriverEarningsAdjustmentRequest r){return ApiResponse.success(service.adjust(r));}}
